190	    /** The other sheets of the sheet's tree, among the sheets that exist: every sheet under its topmost ancestor
191	     *  (the ancestor itself included), following parents and children, each once and never the sheet itself. */
192	    public List<String> tree(String sheetId) {
193	        java.util.LinkedHashSet<String> found = new java.util.LinkedHashSet<>();
194	        String root = sheetId;
195	        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
196	        for (String at = parent(sheetId); at != null && seen.add(at); at = parent(at)) {
197	            root = at;
198	        }
199	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(root));
200	        found.add(root);
201	        while (!pending.isEmpty()) {
202	            for (String child : jdbc.queryForList("SELECT id FROM PUBLIC.sheet WHERE parent_id = ? ORDER BY id",
203	                    String.class, pending.poll())) {
204	                if (found.add(child)) pending.add(child);
205	            }
206	        }
207	        found.remove(sheetId);
208	        return new ArrayList<>(found);
209	    }
210	
211	    private String parent(String sheetId) {
212	        List<String> found = jdbc.query("SELECT parent_id FROM PUBLIC.sheet WHERE id = ?",
213	                (rs, i) -> rs.getString("parent_id"), sheetId);
214	        return found.isEmpty() ? null : found.get(0);
215	    }
216	
217	    /** The ids of the sheet's people whose name or an alias is a name or alias on another sheet of its tree. */
218	    public List<Long> clashing(String sheetId) {
219	        List<String> others = tree(sheetId);
220	        if (others.isEmpty()) return List.of();
221	        java.util.Set<String> keys = new java.util.HashSet<>();
222	        for (String other : others) {
223	            keys.addAll(jdbc.queryForList("SELECT LOWER(name) FROM PUBLIC.person WHERE sheet_id = ?", String.class, other));
224	            keys.addAll(jdbc.queryForList("SELECT LOWER(alias) FROM PUBLIC.person_alias WHERE sheet_id = ?", String.class, other));
225	        }
226	        java.util.Set<Long> clash = new java.util.LinkedHashSet<>();
227	        jdbc.query("SELECT id, LOWER(name) AS k FROM PUBLIC.person WHERE sheet_id = ? ORDER BY id", rs -> {
228	            if (keys.contains(rs.getString("k"))) clash.add(rs.getLong("id"));
229	        }, sheetId);
230	        jdbc.query("SELECT person_id, LOWER(alias) AS k FROM PUBLIC.person_alias WHERE sheet_id = ?", rs -> {
231	            if (keys.contains(rs.getString("k"))) clash.add(rs.getLong("person_id"));
232	        }, sheetId);
233	        return new ArrayList<>(clash);
234	    }
235	
236	    /** The person on the sheet with this name or alias, ignoring case; null when there is none. */
237	    public Person findByName(String sheetId, String name) {
238	        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND (LOWER(name) = LOWER(?)"
239	                + " OR id IN (SELECT a.person_id FROM person_alias a WHERE a.sheet_id = ? AND LOWER(a.alias) = LOWER(?)))"
240	                + " ORDER BY id", ROW, sheetId, name, sheetId, name);
241	        return found.isEmpty() ? null : found.get(0);
242	    }
243	
244	    /** Whether another person on the sheet (other than {@code exceptId}; 0 for none) already has this contact. */
245	    public boolean contactTaken(String sheetId, String contact, long exceptId) {
246	        Integer taken = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
247	                Integer.class, sheetId, contact, exceptId);
248	        return taken != null && taken > 0;
249	    }
250	
251	    public Person add(String sheetId, String name, String grade, Integer terms) {
252	        return add(sheetId, name, grade, terms, null);
253	    }
254	
255	    /** Add a person with their own terms and contact (each null: none). */
256	    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
257	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
258	        jdbc.update(c -> {
259	            PreparedStatement ps = c.prepareStatement(
260	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on, list_position)"
261	                            + " SELECT ?, ?, ?, ?, ?, today, " + NEXT_POSITION + " FROM sheet WHERE id = ?", new String[] { "id" });
262	            ps.setString(1, sheetId);
263	            ps.setString(2, name);
264	            ps.setString(3, grade);
265	            ps.setObject(4, terms, java.sql.Types.INTEGER);
266	            ps.setString(5, contact);
267	            ps.setString(6, sheetId);
268	            return ps;
269	        }, keys);
270	        long id = keys.getKey().longValue();
271	        grade(sheetId, id, grade, null);
272	        return new Person(id, name, grade, 1, 0, null, null, null, false, List.of(new GradeFrom(grade, null)), List.of(), terms, contact, null);
273	    }
274	
275	    /** Swap two people's places in the sheet's list. */
276	    public void swapPositions(String sheetId, long id, long otherId) {
277	        Long mine = position(sheetId, id);
278	        Long theirs = position(sheetId, otherId);
279	        jdbc.update("UPDATE person SET list_position = ? WHERE id = ? AND sheet_id = ?", theirs, id, sheetId);
280	        jdbc.update("UPDATE person SET list_position = ? WHERE id = ? AND sheet_id = ?", mine, otherId, sheetId);
281	    }
282	
283	    private Long position(String sheetId, long id) {
284	        return jdbc.queryForObject("SELECT list_position FROM person WHERE id = ? AND sheet_id = ?", Long.class, id, sheetId);
285	    }
286	
287	    /** Whether the sheet has this person. */
288	    public boolean exists(String sheetId, long id) {
289	        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE id = ? AND sheet_id = ?",
290	                Integer.class, id, sheetId);
291	        return known != null && known > 0;
292	    }
293	
294	    public boolean update(String sheetId, long id, long version, String name, Integer terms) {
295	        return jdbc.update(
296	                "UPDATE person SET name = ?, terms = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
297	                name, terms, id, sheetId, version) > 0;
298	    }
299	
300	    /** Change a person's name, own terms and contact (each null: none), if they are still at {@code version}, moving them to the next version;
301	     *  false when the sheet has no such person at that version. Their grades are given by {@link #grade}. */
302	    public boolean update(String sheetId, long id, long version, String name, Integer terms, String contact) {
303	        return jdbc.update(
304	                "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
305	                name, terms, contact, id, sheetId, version) > 0;
306	    }
307	
308	    /** Copy a person onto another sheet, as added there on its today: their name, the grade they were first given,
309	     *  every grade they were given (with its from-date), their terms, contact and aliases (in the order they were
310	     *  added), with no statements, and the sheet they came from; the new person's id. Their claims are moved by the caller. */
311	    public long transferIn(String fromSheet, long id, String toSheet) {
312	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
313	        jdbc.update(c -> {
314	            PreparedStatement ps = c.prepareStatement(
315	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on, list_position, origin_sheet)"
316	                            + " SELECT ?, p.name, p.grade, p.terms, p.contact, (SELECT s.today FROM sheet s WHERE s.id = ?),"
317	                            + " (SELECT COALESCE(MAX(q.list_position), 0) + 1 FROM person q WHERE q.sheet_id = ?), ?"
318	                            + " FROM person p WHERE p.id = ? AND p.sheet_id = ?", new String[] { "id" });
319	            ps.setString(1, toSheet);
320	            ps.setString(2, toSheet);
321	            ps.setString(3, toSheet);
322	            ps.setString(4, fromSheet);
323	            ps.setLong(5, id);
324	            ps.setString(6, fromSheet);
325	            return ps;
326	        }, keys);
327	        long arrived = keys.getKey().longValue();
328	        for (GradeFrom g : grades(fromSheet, id)) {
329	            grade(toSheet, arrived, g.grade(), g.from() == null ? null : LocalDate.parse(g.from()));
330	        }
331	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) SELECT ?, ?, alias FROM person_alias"
332	                + " WHERE sheet_id = ? AND person_id = ? ORDER BY id", toSheet, arrived, fromSheet, id);
333	        return arrived;
334	    }
335	
336	    /** Take a person off the sheet entirely: their patron links (both ways), pool memberships, closed periods'
337	     *  figures, watchers, holds, statements, grades and aliases go with them. Their claims must already be gone. */
338	    public void remove(String sheetId, long id) {
339	        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
340	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", sheetId, id);
341	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", sheetId, id);
342	        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, id);
343	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, id);
344	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
345	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, id);
346	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, id);
347	        jdbc.update("DELETE FROM person WHERE id = ? AND sheet_id = ?", id, sheetId);
348	    }
349	
350	    /** Merge one person into another: the merged name and aliases become the other's aliases (name first); the
351	     *  merged person's patrons are added to the other's (not themselves, no repeats), anyone naming the merged
352	     *  person names the other instead (no repeats); pool memberships move to the other (shares added, at most
353	     *  100.00, when the other is already a member); closed periods' figures are added to the other's. Their
354	     *  statements, holds, grades, watchers and contact go with them, and the merged person leaves the sheet.
355	     *  Their claims must already have been moved. */
356	    public void merge(String sheetId, long fromId, long intoId) {
357	        String name = jdbc.queryForObject("SELECT name FROM person WHERE id = ? AND sheet_id = ?", String.class, fromId, sheetId);
358	        List<String> aliases = jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY id",
359	                String.class, sheetId, fromId);
360	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
361	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, intoId, name);
362	        for (String alias : aliases) {
363	            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, intoId, alias);
364	        }
365	
366	        // The merged person's patrons become the other's.
367	        jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id) SELECT sheet_id, ?, patron_id FROM patron p"
368	                + " WHERE p.sheet_id = ? AND p.person_id = ? AND p.patron_id <> ? AND NOT EXISTS (SELECT 1 FROM patron q"
369	                + " WHERE q.person_id = ? AND q.patron_id = p.patron_id) ORDER BY p.seq", intoId, sheetId, fromId, intoId, intoId);
370	        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
371	        // Anyone naming the merged person names the other instead.
372	        jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id, seq) SELECT sheet_id, person_id, ?, seq FROM patron p"
373	                + " WHERE p.sheet_id = ? AND p.patron_id = ? AND p.person_id <> ? AND NOT EXISTS (SELECT 1 FROM patron q"
374	                + " WHERE q.person_id = p.person_id AND q.patron_id = ?)", intoId, sheetId, fromId, intoId, intoId);
375	        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND patron_id = ?", sheetId, fromId);
376	
377	        // Pool memberships move; shares are added where the other is already a member.
378	        jdbc.update("UPDATE pool_member m SET share = LEAST(100.00, share + (SELECT f.share FROM pool_member f"
379	                + " WHERE f.sheet_id = m.sheet_id AND f.pool_name = m.pool_name AND f.person_id = ?))"
380	                + " WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS (SELECT 1 FROM pool_member f"
381	                + " WHERE f.sheet_id = m.sheet_id AND f.pool_name = m.pool_name AND f.person_id = ?)",
382	                fromId, sheetId, intoId, fromId);
383	        jdbc.update("DELETE FROM pool_member m WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS (SELECT 1 FROM"
384	                + " pool_member o WHERE o.sheet_id = m.sheet_id AND o.pool_name = m.pool_name AND o.person_id = ?)",
385	                sheetId, fromId, intoId);
386	        jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
387	
388	        // A closed period's figure follows the claims.
389	        jdbc.update("UPDATE period_person_total t SET total = total + (SELECT f.total FROM period_person_total f"
390	                + " WHERE f.period_id = t.period_id AND f.person_id = ?) WHERE t.sheet_id = ? AND t.person_id = ?"
391	                + " AND EXISTS (SELECT 1 FROM period_person_total f WHERE f.period_id = t.period_id AND f.person_id = ?)",
392	                fromId, sheetId, intoId, fromId);
393	        jdbc.update("DELETE FROM period_person_total t WHERE t.sheet_id = ? AND t.person_id = ? AND EXISTS (SELECT 1"
394	                + " FROM period_person_total o WHERE o.period_id = t.period_id AND o.person_id = ?)", sheetId, fromId, intoId);
395	        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
396	
397	        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
398	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
399	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
400	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
401	        jdbc.update("DELETE FROM person WHERE id = ? AND sheet_id = ?", fromId, sheetId);
402	    }
