package net.officefloor.hq.app.history;

import java.sql.Date;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.server.http.HttpHeader;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** A signed-in user's screen showing a sheet as of a date (the X-As-Of header, yyyy-mm-dd): the sheet as it stood
 *  at the end of that day. Every change kept in row_change (see {@link RowCapture}) made while the sheet's today
 *  was on or before the date counts, in the order made, every later one does not (the sheet itself always
 *  exists); the date stands in for the sheet's today. A read replays those changes into the asof schema's tables,
 *  runs the usual read against them, and removes them again, all in one transaction, so no other read sees them.
 *  While the date is set, every change is refused. */
@Component
public class AsOfView {

    public static final String HEADER = "X-As-Of";

    private final JdbcTemplate jdbc;
    private final RowCaptureInstaller installer;
    private final TransactionTemplate transaction;

    public AsOfView(JdbcTemplate jdbc, RowCaptureInstaller installer, PlatformTransactionManager transactions) {
        this.jdbc = jdbc;
        this.installer = installer;
        this.transaction = new TransactionTemplate(transactions);
    }

    /** The as-of date the request's screen shows; null when it shows the sheet as it is now. */
    public static LocalDate of(ServerHttpConnection connection) throws BadRequestException {
        String raw = "";
        for (HttpHeader header : connection.getRequest().getHeaders()) {
            if (HEADER.equalsIgnoreCase(header.getName())) {
                raw = header.getValue() == null ? "" : header.getValue().trim();
                break;
            }
        }
        if (raw.isEmpty()) return null;
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("as-of date must be yyyy-mm-dd");
        }
    }

    /** Refuse any change made from a screen showing the sheet as of a date (400, nothing written). */
    public static void refuse(ServerHttpConnection connection) throws BadRequestException {
        if (of(connection) != null) {
            throw new BadRequestException("the sheet is shown as of a date: nothing can be changed");
        }
    }

    /** The read, as the request's screen shows the sheet: as of its date when one is set, else as it is now. */
    public <T> T read(ServerHttpConnection connection, String sheetId, Supplier<T> read) throws BadRequestException {
        LocalDate day = of(connection);
        if (day == null) return read.get();
        return transaction.execute(status -> {
            Map<String, List<Object[]>> rows = replay(sheetId, day);
            for (Map.Entry<String, List<Object[]>> e : rows.entrySet()) {
                RowCaptureInstaller.Table table = installer.tables().get(e.getKey());
                String marks = String.join(", ", table.columns().stream().map(c -> "?").toList());
                for (Object[] row : e.getValue()) {
                    jdbc.update("INSERT INTO ASOF.\"" + table.name() + "\" VALUES (" + marks + ")", row);
                }
            }
            if (rows.getOrDefault("SHEET", List.of()).isEmpty()) {
                jdbc.update("INSERT INTO ASOF.SHEET SELECT * FROM PUBLIC.SHEET WHERE id = ?", sheetId);
            }
            jdbc.update("UPDATE ASOF.SHEET SET today = ? WHERE id = ?", Date.valueOf(day), sheetId);
            jdbc.execute("SET SCHEMA ASOF");
            try {
                return read.get();
            } finally {
                jdbc.execute("SET SCHEMA PUBLIC");
                for (RowCaptureInstaller.Table table : installer.tables().values()) {
                    jdbc.update("DELETE FROM ASOF.\"" + table.name() + "\" WHERE \"" + table.columns().get(table.sheetColumn())
                            + "\" = ?", sheetId);
                }
            }
        });
    }

    /** The sheet's rows as of the end of a day, by table: the kept changes made while its today was on or before
     *  it, applied in the order made. An insert adds its row (the sheet's own always counts); an update changes
     *  the columns it changed of the row it changed (found by its primary key, else by all its values), and a
     *  delete removes that row; one whose row is not there (it was added later) changes nothing. */
    private Map<String, List<Object[]>> replay(String sheetId, LocalDate day) {
        Map<String, List<Object[]>> rows = new LinkedHashMap<>();
        Date on = Date.valueOf(day);
        jdbc.query("SELECT on_date, table_name, old_row, new_row FROM ROW_CHANGE WHERE sheet_id = ? ORDER BY id", rs -> {
            RowCaptureInstaller.Table table = installer.tables().get(rs.getString("table_name"));
            if (table == null) return;
            Object[] before = RowCapture.read(rs.getBytes("old_row"));
            Object[] after = RowCapture.read(rs.getBytes("new_row"));
            boolean counts = !rs.getDate("on_date").after(on) || (before == null && table.name().equals("SHEET"));
            if (!counts) return;
            List<Object[]> kept = rows.computeIfAbsent(table.name(), k -> new ArrayList<>());
            if (before == null) {
                if (!table.key().isEmpty()) {
                    int same = find(kept, table, after);
                    if (same >= 0) kept.remove(same);
                }
                kept.add(after.clone());
                return;
            }
            int found = find(kept, table, before);
            if (found < 0) return;
    }

    /** The ids of the sheet's people with a hold in force on the sheet's today (a hold whose dates include it). */
    private Set<Long> heldToday(String sheetId) {
        return new HashSet<>(jdbc.queryForList("SELECT DISTINCT h.person_id FROM person_hold h"
                + " JOIN sheet s ON s.id = h.sheet_id WHERE h.sheet_id = ?"
                + " AND (h.from_date IS NULL OR h.from_date <= COALESCE(s.today, CURRENT_DATE))"
                + " AND (h.to_date IS NULL OR h.to_date >= COALESCE(s.today, CURRENT_DATE))", Long.class, sheetId));
    }

    /** Each member's cut of the pot (null for a member that is not current). A member with a cut is one current,
     *  neither retired nor held on the sheet's today;
     *  each such member's cut is the pot times their share divided by the shares of the members with a cut added
     *  up, rounded half to even to two decimals (0.00 for any other member, and for every member when none has a
     *  cut); the remainder, the pot minus the cuts added up, goes to the member with a cut with the largest share
     *  (the earliest added on a tie), so the cuts total exactly the pot. */
    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
        List<Boolean> withCut = new ArrayList<>();
        BigDecimal shares = BigDecimal.ZERO;
        for (PoolMember m : members) {
            boolean has = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
            withCut.add(has);
            if (has) shares = shares.add(new BigDecimal(m.share()));
        }
        List<BigDecimal> cuts = new ArrayList<>();
        int largest = -1;
        BigDecimal sum = BigDecimal.ZERO;
        for (int i = 0; i < members.size(); i++) {
            PoolMember m = members.get(i);
            boolean has = withCut.get(i) && shares.signum() > 0;
            BigDecimal share = has ? new BigDecimal(m.share()) : BigDecimal.ZERO;
            BigDecimal cut = has ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
                    : BigDecimal.ZERO.setScale(2);
            cuts.add(cut);
            sum = sum.add(cut);
            if (has && (largest < 0 || share.compareTo(new BigDecimal(members.get(largest).share())) > 0)) {
                largest = i;
            }
        }
        if (largest >= 0) cuts.set(largest, cuts.get(largest).add(pot.subtract(sum)));
        List<PoolMember> cut = new ArrayList<>();
        for (int i = 0; i < members.size(); i++) {
            PoolMember m = members.get(i);
            cut.add(new PoolMember(m.personId(), m.pool(), m.name(), m.share(), m.retired(),
                    m.current() ? cuts.get(i).setScale(2).toPlainString() : null, m.from(), m.to(), m.current()));
        }
        return cut;
    }

    /** The sheet's pools, by name, each with its members (people and pools) in the order they were added, and
     *  their cuts of the pool's pot when the pool is balanced, has a pot and has a current member not retired. A
     *  pool's total share counts every current member's share, a retired member's included. A pool that is a member of none has
     *  the sheet's pot; a pool that is a member of another has its cut there as its pot (none when that pool
     *  shows no cuts). */
    public List<Pool> list(String sheetId) {
        Map<String, List<PoolMember>> members = new LinkedHashMap<>();
        for (String name : jdbc.queryForList("SELECT name FROM pool WHERE sheet_id = ? ORDER BY name", String.class,
                sheetId)) {
            members.put(name, new ArrayList<>());
        }
        Map<String, String> parents = new HashMap<>();
        jdbc.query("SELECT m.pool_name, m.person_id, m.member_pool, p.name, m.share, p.retired_from, m.from_date,"
                + " m.to_date, (m.from_date IS NULL OR m.from_date <= COALESCE(s.today, CURRENT_DATE))"
                + " AND (m.to_date IS NULL OR m.to_date >= COALESCE(s.today, CURRENT_DATE)) AS is_current"
                + " FROM pool_member m JOIN sheet s ON s.id = m.sheet_id"
                + " LEFT JOIN person p ON p.id = m.person_id WHERE m.sheet_id = ? ORDER BY m.id", rs -> {
            List<PoolMember> of = members.get(rs.getString("pool_name"));
            if (of == null) return;
            String share = rs.getBigDecimal("share").setScale(2).toPlainString();
            String memberPool = rs.getString("member_pool");
            java.sql.Date fromDate = rs.getDate("from_date");
            java.sql.Date toDate = rs.getDate("to_date");
            String from = fromDate == null ? null : fromDate.toLocalDate().toString();
            String to = toDate == null ? null : toDate.toLocalDate().toString();
            boolean current = rs.getBoolean("is_current");
            if (memberPool != null) {
                parents.put(memberPool, rs.getString("pool_name"));
                of.add(new PoolMember(null, memberPool, memberPool, share, false, null, from, to, current));
            } else if (rs.getString("name") != null) {
                of.add(new PoolMember(rs.getLong("person_id"), null, rs.getString("name"), share,
                        rs.getDate("retired_from") != null, null, from, to, current));
            }
        }, sheetId);
        BigDecimal sheetPot = pot(sheetId);
        Set<Long> held = heldToday(sheetId);
        Map<String, Pool> done = new HashMap<>();
        List<Pool> pools = new ArrayList<>();
        for (String name : members.keySet()) {
            pools.add(resolve(name, members, parents, sheetPot, held, done));
        }
        return pools;
    }

    /** The named pool with its cuts, resolving the pool above it first for its pot. */
    private static Pool resolve(String name, Map<String, List<PoolMember>> members, Map<String, String> parents,
            BigDecimal sheetPot, Set<Long> held, Map<String, Pool> done) {
        Pool known = done.get(name);
        if (known != null) return known;
        BigDecimal pot = sheetPot;
        String parent = parents.get(name);
        if (parent != null) {
            pot = null;
            if (members.containsKey(parent)) {
                for (PoolMember m : resolve(parent, members, parents, sheetPot, held, done).members()) {
                    if (name.equals(m.pool()) && m.cut() != null) pot = new BigDecimal(m.cut());
                }
            }
        }
        List<PoolMember> of = members.get(name);
        BigDecimal total = of.stream().filter(PoolMember::current).map(m -> new BigDecimal(m.share()))
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
        boolean balanced = total.compareTo(HUNDRED) == 0;
        boolean allRetired = of.stream().filter(PoolMember::current).allMatch(PoolMember::retired);
        Pool pool = new Pool(name, balanced && pot != null && !allRetired ? cut(of, pot, held) : of,
                total.toPlainString(), balanced);
        done.put(name, pool);
        return pool;
    }
}

